(() => {
'use strict';
const shapes={home:'<path d="m3 10 9-7 9 7v10H3zM9 20v-7h6v7"/>',venue:'<path d="M4 10v11h16V10M3 10l2-7h14l2 7M3 10c0 4 6 4 6 0 0 4 6 4 6 0 0 4 6 4 6 0M9 21v-7h6v7"/>',music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="17" cy="16" rx="3" ry="3"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6M17 2v6M3 11h18m-13 5 3 3 5-6"/>',zones:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',radio:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="m6 7 11-5M15 12h3M15 16h3"/><circle cx="8" cy="14" r="2"/>',ads:'<path d="m3 10 15-6v16L3 14zM7 15l1 6h4l-2-5M21 9v6"/>',analytics:'<path d="M4 20V10M10 20V4M16 20v-8M22 20V7"/>',billing:'<rect x="2" y="5" width="20" height="15" rx="3"/><path d="M2 10h20M6 16h4"/>',support:'<path d="M4 13v-2a8 8 0 0116 0v2M4 12H2v6h4v-6zm16 0h2v6h-4v-6zM18 19c0 3-4 3-6 3"/>',plus:'<path d="M12 4v16M4 12h16"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',bell:'<path d="M5 9a7 7 0 0114 0v7l2 2H3l2-2zM9 22h6"/>',down:'<path d="m6 9 6 6 6-6"/>',close:'<path d="m5 5 14 14M5 19 19 5"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',play:'<path d="M8 4.5 20 12 8 19.5z"/>',pause:'<rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/>',prev:'<path d="m16 5-9 7 9 7M5 5v14"/>',next:'<path d="m8 5 9 7-9 7M19 5v14"/>',volume:'<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 010 8M18 5a10 10 0 010 14"/>',heart:'<path d="M12 20 4 12C-2 5 8 0 12 7c4-7 14-2 8 5z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',edit:'<path d="m4 15 12-12 5 5L9 20l-6 1zM13 6l5 5"/>'};
const icon=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(shapes[n]||shapes.music)+'</svg>';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const menu=[['home','Главная','home'],['venues','Мои заведения','venue'],['playlists','Плейлисты','music'],['schedule','Расписание','calendar'],['zones','Зоны и устройства','zones'],['radio','Радио и джинглы','radio'],['ads','Реклама и анонсы','ads'],['analytics','Аналитика','analytics'],['billing','Тариф и оплата','billing'],['support','Поддержка','support']];
const tracks=[{name:'Morning Soul',genre:'Soul / Jazz',mood:'Утро',who:'Nico',length:'26 сек'},{name:'Sunset Lounge',genre:'Lounge / Acoustic',mood:'День',who:'Sandra',length:'23 сек'},{name:'Night Groove',genre:'Funk / Disco',mood:'Вечер',who:'Leo',length:'17 сек'},{name:'Soft Motion',genre:'Ambient / Chill',mood:'Спокойствие',who:'Mia',length:'28 сек'}];
let venues=[{id:'v1',name:'Кофейня на углу',type:'Кофейня',address:'Демо-адрес · центр города',art:0},{id:'v2',name:'Тёплый вечер',type:'Ресторан',address:'Демо-адрес · набережная',art:1},{id:'v3',name:'Винил Бар',type:'Бар',address:'Демо-адрес · старый город',art:2}];
let zoneList=[{id:'z1',venue:'v1',name:'Основной зал',track:0,volume:65,on:true},{id:'z2',venue:'v1',name:'Терраса',track:1,volume:40,on:false},{id:'z3',venue:'v2',name:'Ресторан',track:1,volume:45,on:true},{id:'z4',venue:'v3',name:'Барная стойка',track:2,volume:60,on:true}];
let customLists=[],drafts=[],schedules={},radioDraft={name:'Радио «Кофейня на углу»',greeting:'Добро пожаловать! Устраивайтесь поудобнее. Мы выбрали музыку для вашего дня.'},favs=[];
const key='promo-air-cabinet-v1';
try{const s=JSON.parse(localStorage.getItem(key));if(s&&s.version===1){if(Array.isArray(s.venues)&&s.venues.length<=50&&s.venues.every(v=>typeof v.id==='string'&&typeof v.name==='string'&&typeof v.type==='string'&&typeof v.address==='string'&&Number.isInteger(v.art)&&v.art>=0&&v.art<6))venues=s.venues;if(Array.isArray(s.zones)&&s.zones.length<=100&&s.zones.every(z=>typeof z.id==='string'&&typeof z.venue==='string'&&typeof z.name==='string'&&Number.isInteger(z.track)&&z.track>=0&&z.track<4&&Number.isFinite(z.volume)&&z.volume>=0&&z.volume<=100&&typeof z.on==='boolean'))zoneList=s.zones;if(Array.isArray(s.lists)&&s.lists.every(l=>typeof l.name==='string'&&Number.isInteger(l.track)&&l.track>=0&&l.track<4))customLists=s.lists.slice(0,50);if(Array.isArray(s.drafts)&&s.drafts.every(d=>typeof d.name==='string'&&typeof d.text==='string'&&typeof d.when==='string'))drafts=s.drafts.slice(0,50);if(s.schedules&&typeof s.schedules==='object'&&!Array.isArray(s.schedules))Object.entries(s.schedules).forEach(([k,v])=>{if(Array.isArray(v)&&v.length===4&&v.every(t=>Number.isInteger(t)&&t>=0&&t<4))schedules[k]=v});if(s.radio&&typeof s.radio.name==='string'&&typeof s.radio.greeting==='string')radioDraft=s.radio;if(Array.isArray(s.favs))favs=s.favs.filter(n=>Number.isInteger(n)&&n>=0&&n<4)}}catch{}
const main=document.querySelector('#main'),audio=document.querySelector('#audio'),dialog=document.querySelector('#dialog');let screen='home',current=0,selectedVenue=venues[0]?.id||'',day=0,filter='Все',query='',request=0,playedSeconds=0,lastTime=0,toastTimer,modalSubmit=null;
audio.volume=.65;
function notify(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200)}
function save(){try{localStorage.setItem(key,JSON.stringify({version:1,venues,zones:zoneList,lists:customLists,drafts,schedules,radio:radioDraft,favs}));return true}catch{return false}}
function storedNotice(message){notify(save()?message:'Настройки действуют до закрытия страницы. Сохранение недоступно.')}
const button=(label,action,kind='')=>'<button class="button '+kind+'" data-action="'+action+'">'+label+'</button>';
const heading=(title,description,action='')=>'<div class="page-heading"><div><div class="overline">ВАШЕ ПРОСТРАНСТВО / PROMO.AIR</div><h1>'+title+'</h1><p>'+description+'</p></div>'+action+'</div>';
const cover=i=>'<span class="cover cover-'+i+'"></span>';
const venueName=id=>venues.find(v=>v.id===id)?.name||'Заведение';
function venueSelect(){return '<select class="select-small" data-venue aria-label="Выбрать заведение">'+venues.map(v=>'<option value="'+esc(v.id)+'" '+(selectedVenue===v.id?'selected':'')+'>'+esc(v.name)+'</option>').join('')+'</select>'}
const options=n=>tracks.map((t,i)=>'<option value="'+i+'" '+(n===i?'selected':'')+'>'+t.name+'</option>').join('');
const stat=(ico,label,value,tail='')=>'<article class="stat"><span class="stat-icon">'+icon(ico)+'</span><div><small>'+label+'</small><strong>'+value+(tail?'<span>'+tail+'</span>':'')+'</strong></div></article>';
function slots(){const k=selectedVenue+':'+day;if(!schedules[k])schedules[k]=[0,1,2,3];return schedules[k]}
function home(){return '<section class="hero"><div><div class="overline">ДОБРО ПОЖАЛОВАТЬ, НИКО</div><h1>Ваше пространство<br><em>звучит.</em></h1><p>Выбирайте музыку, создавайте атмосферу и управляйте звучанием ваших мест.</p><div class="actions"><button class="button primary" data-action="toggle-audio">'+icon('play')+'Запустить музыку</button>'+button('Как работает кабинет','tour')+'</div></div><a class="hero-badge" href="#billing"><strong>7 дней</strong><small>без оплаты</small></a></section><section class="stats" aria-label="Обзор демо-кабинета">'+stat('venue','Мои заведения',venues.length,'в демо-кабинете')+stat('music','Музыкальные форматы',tracks.length,'готовы к прослушиванию')+stat('zones','Музыкальные зоны',zoneList.length,'макет управления')+'</section><div class="home-grid"><section class="panel"><div class="panel-head"><h2>Сейчас в плеере</h2><span class="demo-chip">АУДИОЭСКИЗ</span></div><div class="now-art"><span class="cover cover-'+current+'"></span><div><strong>'+tracks[current].name+'</strong><small>'+tracks[current].who+' · подборка настроения</small><div class="tags"><span class="tag">'+tracks[current].genre+'</span></div></div></div><div class="now-actions"><button class="button primary" data-action="toggle-audio">'+icon(audio.paused?'play':'pause')+(audio.paused?'Слушать эскиз':'Пауза')+'</button><button class="icon-btn '+(favs.includes(current)?'active-favorite':'')+'" data-action="favorite" aria-label="В избранное">'+icon('heart')+'</button></div></section><section class="panel"><div class="panel-head"><h2>Ритм вашего дня</h2><button class="text-btn" data-page="schedule">Изменить</button></div><div class="home-schedule">'+['09:00','13:00','18:00','22:00'].map((h,i)=>'<div><i></i><time>'+h+'</time><span>'+tracks[slots()[i]].name+'</span><button class="icon-btn" data-play-track="'+slots()[i]+'" aria-label="Слушать '+h+'">'+icon('play')+'</button></div>').join('')+'</div></section><section class="panel radio-card"><div class="panel-head"><h2>Ваше радио</h2></div><img src="/assets/microphone.webp" alt="Оранжевый хромированный микрофон"><p>Джинглы, приветствия и анонсы в характере вашего места.</p><button class="button" data-page="radio">Настроить радио</button></section></div><section class="quick-actions" aria-label="Быстрые действия"><button class="quick" data-action="new-playlist">'+icon('music')+'Создать плейлист</button><button class="quick" data-page="schedule">'+icon('calendar')+'Настроить расписание</button><button class="quick" data-page="zones">'+icon('zones')+'Управлять зонами</button><button class="quick" data-action="new-venue">'+icon('plus')+'Добавить заведение</button></section><p class="demo-note">Демо-кабинет: музыка звучит на этом устройстве, настройки сохраняются в браузере. Реальные заведения и устройства не подключены.</p>'}
function venuesPage(){const shown=venues.filter(v=>(filter==='Все'||v.type===filter)&&v.name.toLowerCase().includes(query.toLowerCase()));return heading('Мои заведения','Всё, что нужно для хорошего звучания каждого места.',button(icon('plus')+'Добавить','new-venue','primary'))+'<div class="toolbar"><div class="filters">'+['Все','Кофейня','Ресторан','Бар','Магазин','Отель','SPA'].map(x=>'<button class="filter" data-filter="'+x+'" aria-pressed="'+(filter===x)+'">'+x+'</button>').join('')+'</div><input class="field" id="local-search" placeholder="Найти заведение" aria-label="Найти заведение" value="'+esc(query)+'"></div><div class="venue-grid">'+(shown.length?shown.map(v=>'<article class="panel venue-card"><div class="venue-art" style="--position:'+['0 0','50% 0','100% 0','0 100%','50% 100%','100% 100%'][v.art]+'"></div><div class="venue-body"><h3>'+esc(v.name)+'</h3><p>'+esc(v.address)+'</p><div class="venue-meta"><span class="status">Демо-пространство</span><small>'+zoneList.filter(z=>z.venue===v.id).length+' зон</small></div><div class="venue-actions"><button class="button" data-venue-zones="'+esc(v.id)+'">Открыть зоны</button><button class="button" data-edit-venue="'+esc(v.id)+'">'+icon('edit')+'Изменить</button></div></div></article>').join(''):'<div class="library-empty">Заведения не найдены. Измените поиск или добавьте новое.</div>')+'</div>'}
function playlistsPage(){const shown=tracks.map((t,i)=>({...t,i})).filter(t=>(filter!=='Избранное'||favs.includes(t.i))&&(filter==='Все'||filter==='Избранное'||t.mood===filter)&&(t.name+' '+t.genre).toLowerCase().includes(query.toLowerCase()));return heading('Плейлисты','Настроения, которые делают ваше пространство особенным.',button(icon('plus')+'Создать плейлист','new-playlist','primary'))+'<div class="curator-note"><span class="curator-art" role="img" aria-label="Сандра"></span><span>Подборки с настроением вашего места</span></div><div class="toolbar"><div class="filters">'+['Все','Утро','День','Вечер','Спокойствие','Избранное'].map(x=>'<button class="filter" data-filter="'+x+'" aria-pressed="'+(filter===x)+'">'+x+'</button>').join('')+'</div><input id="local-search" class="field" placeholder="Название или жанр" aria-label="Поиск плейлистов" value="'+esc(query)+'"></div><div class="playlist-grid">'+(shown.length?shown.map(t=>'<button class="playlist-card '+(current===t.i?'active':'')+'" data-play-track="'+t.i+'">'+cover(t.i)+'<span class="playlist-copy"><strong>'+t.name+'</strong><small>'+t.genre+'</small><span class="tags"><span class="tag">'+t.mood+'</span><span class="tag">Эскиз · '+t.length+'</span></span></span></button>').join(''):'<div class="library-empty">Ничего не найдено. Попробуйте другой фильтр.</div>')+'</div>'+(customLists.length?'<section class="panel" style="margin-top:25px"><div class="panel-head"><h2>Мои плейлисты</h2><span class="demo-chip">ЛОКАЛЬНЫЕ ЧЕРНОВИКИ</span></div><div class="draft-list">'+customLists.map((l,i)=>'<div class="draft-row"><div><strong>'+esc(l.name)+'</strong><p>Основа: '+tracks[l.track].name+'</p></div><button class="icon-btn" data-play-track="'+l.track+'" aria-label="Слушать '+esc(l.name)+'">'+icon('play')+'</button></div>').join('')+'</div></section>':'')+'<p class="demo-note">Четыре коротких инструментальных эскиза демонстрируют интерфейс. Это не каталог треков действующего сервиса.</p>'}
function schedulePage(){return heading('Расписание','Один день. Четыре настроения. Ваш музыкальный сценарий.')+'<div class="toolbar">'+venueSelect()+'<div class="week" aria-label="День недели">'+['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map((d,i)=>'<button data-day="'+i+'" aria-pressed="'+(day===i)+'">'+d+'</button>').join('')+'</div></div><section class="panel"><div class="panel-head"><h2>'+esc(venueName(selectedVenue))+'</h2><span class="demo-chip">ПРИМЕР РАСПИСАНИЯ</span></div><table class="schedule-table"><thead><tr><th>ВРЕМЯ</th><th>МУЗЫКАЛЬНЫЙ ФОРМАТ</th><th class="schedule-place">НАСТРОЕНИЕ</th><th></th></tr></thead><tbody>'+['09:00','13:00','18:00','22:00'].map((h,i)=>'<tr><td><time>'+h+'</time></td><td><select data-slot="'+i+'" aria-label="Музыка в '+h+'">'+options(slots()[i])+'</select></td><td class="schedule-place">'+['Мягкое начало','Время встреч','Вечерний грув','Спокойный финал'][i]+'</td><td><button class="icon-btn" data-play-slot="'+i+'" aria-label="Слушать выбранную музыку в '+h+'">'+icon('play')+'</button></td></tr>').join('')+'</tbody></table><div class="info-line"><p>Изменения сохраняются для выбранного дня и заведения.</p><button class="button primary" data-action="save-schedule">Сохранить расписание</button></div></section><p class="demo-note">Локальный сценарий в браузере. Автоматическое переключение реального эфира и часовой пояс заведения будут подключены при интеграции.</p>'}
function zonesPage(){const list=zoneList.filter(z=>z.venue===selectedVenue);return heading('Зоны и устройства','От основного зала до террасы. У каждого пространства свой звук.',button(icon('plus')+'Добавить зону','new-zone','primary'))+'<div class="toolbar">'+venueSelect()+'<span class="demo-chip">УСТРОЙСТВА НЕ ПОДКЛЮЧЕНЫ</span></div><div class="zone-grid">'+(list.length?list.map(z=>'<article class="panel"><div class="zone-head"><div><h3>'+esc(z.name)+'</h3><p>'+esc(venueName(z.venue))+'</p></div><button class="switch" data-toggle-zone="'+esc(z.id)+'" aria-pressed="'+z.on+'" aria-label="Включить '+esc(z.name)+'"></button></div><div class="zone-body"><label for="z-'+esc(z.id)+'">МУЗЫКАЛЬНЫЙ ФОРМАТ</label><select class="select-small" id="z-'+esc(z.id)+'" data-zone-track="'+esc(z.id)+'">'+options(z.track)+'</select></div><label class="zone-volume">'+icon('volume')+'<input type="range" min="0" max="100" value="'+z.volume+'" data-zone-volume="'+esc(z.id)+'" aria-label="Громкость '+esc(z.name)+'"><output>'+z.volume+'%</output></label><div class="device-state">Демонстрационная зона · подключение ожидается</div></article>').join(''):'<div class="library-empty">Здесь ещё нет зон. Добавьте зал, террасу или другую часть заведения.</div>')+'</div><p class="demo-note">Это макет управления. Настройки зон не меняют громкость устройства, на котором открыт кабинет.</p>'}
function radioPage(){return heading('Радио и джинглы','Музыкальный характер, который узнают с первых нот.')+'<div class="split"><section class="panel"><div class="panel-head"><h2>Голос вашего места</h2><span class="demo-chip">ЧЕРНОВИК</span></div><form id="radio-form" class="form-stack"><label>Название радио<input name="radio-name" class="field" required maxlength="80" value="'+esc(radioDraft.name)+'"></label><label>Приветствие для гостей<textarea name="greeting" class="field" required maxlength="1000">'+esc(radioDraft.greeting)+'</textarea></label><div class="save-row"><small>Сохранение текста в этом браузере</small><button class="button primary" type="submit">Сохранить черновик</button></div></form></section><section class="panel"><div class="radio-preview"><img src="/assets/microphone.webp" alt="Глянцевый оранжевый микрофон"><div><h3>У бренда есть голос.</h3><p>Фирменные джинглы, приветствия и короткие объявления.</p></div></div><div class="draft-list"><div class="draft-row"><div><strong>Фирменный джингл</strong><p>Концепция звучания вашего бренда</p></div><button class="text-btn" data-action="jingle">Подготовить бриф</button></div></div><p class="demo-note">Запись голоса, генерация и трансляция в эфир здесь ещё не подключены.</p></section></div>'}
function adsPage(){return heading('Реклама и анонсы','Расскажите гостям о том, что происходит в вашем пространстве.',button(icon('plus')+'Новый анонс','new-ad','primary'))+'<section class="panel"><div class="panel-head"><h2>Ваши объявления</h2><span class="demo-chip">ЧЕРНОВИКИ</span></div>'+(drafts.length?'<div class="draft-list">'+drafts.map((d,i)=>'<div class="draft-row"><div><strong>'+esc(d.name)+'</strong><p>'+esc(d.text)+'</p><p>'+esc(d.when)+'</p></div><button class="text-btn" data-edit-ad="'+i+'">Изменить</button></div>').join('')+'</div>':'<div class="empty-state">Здесь появятся ваши анонсы.<br>Создайте первое сообщение о событии, меню или специальном предложении.</div>')+'</section><p class="demo-note">Объявления сохраняются как локальные текстовые черновики. Они не отправляются в эфир.</p>'}
function analyticsPage(){return heading('Аналитика','Понятная картина вашего звучания.')+'<section class="stats">'+stat('clock','Прослушано здесь',Math.floor(playedSeconds/60),'минут за этот просмотр')+stat('venue','Заведений в макете',venues.length)+stat('music','Моих плейлистов',customLists.length)+'</section><section class="panel"><div class="panel-head"><h2>Данные вашего эфира</h2><span class="demo-chip">НЕТ ПОДКЛЮЧЕНИЯ</span></div><div class="empty-state">Подключите реальные устройства, чтобы видеть время вещания и историю воспроизведения.<br>Данные о посещаемости появятся только при отдельной интеграции.</div></section>'}
function billingPage(){const prices=[['Старт','4 990',['1 точка','Базовая библиотека','Базовая аналитика']],['Бизнес','9 990',['1 точка','Расписание по часам','Джинглы и рекламные слоты']],['Сеть','14 990',['От 2 точек','Премиум-каталог','Персональный менеджер']],['Радио полного цикла','20 000',['Собственный эфир','Ведущие и джинглы','Освещение событий']]];return heading('Тариф и оплата','Выберите решение в масштабе вашего бизнеса.')+'<div class="panel" style="margin-bottom:23px"><div class="panel-head" style="margin:0"><div><h2>Попробуйте свой звук</h2><p class="demo-note">7 дней без оплаты при подключении в действующем сервисе.</p></div><span class="demo-chip">ДЕМО БЕЗ ПОДПИСКИ</span></div></div><div class="plan-grid">'+prices.map(p=>'<article class="panel"><h3>'+p[0]+'</h3><div class="plan-price">'+p[1]+' ₽</div><p>в месяц</p><ul>'+p[2].map(f=>'<li>'+f+'</li>').join('')+'</ul><a class="button" href="https://promo-music.ru/login">Перейти к подключению</a></article>').join('')+'</div><p class="demo-note">Маркетинговые цены из предложения на 15.10.2026. Итоговая стоимость и состав плана подтверждаются в действующем кабинете. Здесь нет платёжной формы и реальной подписки.</p>'}
function supportPage(){return heading('Поддержка','Поможем разобраться с вашим музыкальным пространством.')+'<div class="split"><section class="panel faq"><h2>Частые вопросы</h2><details open><summary>Как запустить музыку?</summary><p>Откройте «Плейлисты» и выберите формат. В нижней панели доступны пауза, переключение, перемотка и громкость. Сейчас звучат демонстрационные аудиоэскизы.</p></details><details><summary>Где сохраняются изменения?</summary><p>Заведения, зоны и расписание этого прототипа сохраняются только в браузере. Они не связаны с реальным аккаунтом PROMO.MUSIC.</p></details><details><summary>Как подключить своё заведение?</summary><p>Перейдите в действующий кабинет PROMO.MUSIC и выберите роль заведения. Подключение и оплата происходят там.</p></details></section><section class="panel"><h2>Начнём со знакомства</h2><p class="demo-note">Войдите в действующий сервис, чтобы перейти к подключению и поддержке.</p><a class="button primary" href="https://promo-music.ru/login" style="margin-top:25px">Открыть PROMO.MUSIC</a><div class="credit">Design by <b>Promo.Art</b></div></section></div>'}
function searchPage(){const q=query.toLowerCase();const vs=venues.filter(v=>(v.name+' '+v.type).toLowerCase().includes(q)),ts=tracks.map((t,i)=>({...t,i})).filter(t=>(t.name+' '+t.genre).toLowerCase().includes(q));return heading('Результаты поиска','По запросу «'+esc(query)+'»')+'<div class="search-results">'+vs.map(v=>'<button class="search-result" data-venue-zones="'+esc(v.id)+'"><strong>'+esc(v.name)+'</strong><small>Заведение</small></button>').join('')+ts.map(t=>'<button class="search-result" data-play-track="'+t.i+'"><strong>'+t.name+'</strong><small>'+t.genre+'</small></button>').join('')+(!vs.length&&!ts.length?'<div class="library-empty">Ничего не найдено. Попробуйте название или жанр.</div>':'')+'</div>'}
const pages={home,venues:venuesPage,playlists:playlistsPage,schedule:schedulePage,zones:zonesPage,radio:radioPage,ads:adsPage,analytics:analyticsPage,billing:billingPage,support:supportPage,search:searchPage};
function render(next=screen,keep=false){if(!pages[next])next='home';screen=next;if(!keep){filter='Все';query=''}main.innerHTML=pages[screen]();document.querySelectorAll('.nav-link').forEach(b=>{if(b.dataset.page===screen)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(!keep){if(location.hash!=='#'+screen)history.pushState(null,'','#'+screen);window.scrollTo({top:0,behavior:'instant'})}closeMenu();bindPage();sync()}
function bindPage(){const local=main.querySelector('#local-search');if(local)local.oninput=()=>{const pos=local.selectionStart;query=local.value;render(screen,true);const n=document.querySelector('#local-search');n.focus();n.setSelectionRange(pos,pos)};main.querySelectorAll('[data-venue]').forEach(s=>s.onchange=()=>{selectedVenue=s.value;render(screen,true)});main.querySelectorAll('[data-slot]').forEach(s=>s.onchange=()=>slots()[+s.dataset.slot]=+s.value);main.querySelectorAll('[data-zone-track]').forEach(s=>s.onchange=()=>{zoneList.find(z=>z.id===s.dataset.zoneTrack).track=+s.value;save()});main.querySelectorAll('[data-zone-volume]').forEach(s=>s.oninput=()=>{zoneList.find(z=>z.id===s.dataset.zoneVolume).volume=+s.value;s.nextElementSibling.textContent=s.value+'%';save()});const form=main.querySelector('#radio-form');if(form)form.onsubmit=e=>{e.preventDefault();const d=new FormData(form);radioDraft={name:d.get('radio-name').trim(),greeting:d.get('greeting').trim()};storedNotice('Черновик радио сохранён в браузере')}}
function modal(title,body,submit,callback){document.querySelector('#modal-title').textContent=title;document.querySelector('#modal-body').innerHTML=body;document.querySelector('#modal-actions').innerHTML=submit?'<button type="button" class="button" data-close-modal>Отмена</button><button type="submit" class="button primary">'+submit+'</button>':'<button type="button" class="button" data-close-modal>Понятно</button>';modalSubmit=callback;dialog.showModal()}
const field=(label,name,value='',type='text',required=true)=>'<label class="modal-field">'+label+'<input class="field" name="'+name+'" type="'+type+'" maxlength="100" value="'+esc(value)+'" '+(required?'required':'')+'></label>';
function editVenue(id){const v=venues.find(v=>v.id===id);modal(v?'Изменить заведение':'Добавить заведение',field('Название','name',v?.name||'')+field('Адрес или заметка','address',v?.address||'','text',false)+'<label class="modal-field">Тип заведения<select name="type" class="field">'+['Кофейня','Ресторан','Бар','Магазин','Отель','SPA'].map((t,i)=>'<option value="'+i+'" '+(v?.art===i?'selected':'')+'>'+t+'</option>').join('')+'</select></label><p>Сохранится в демо-кабинете этого браузера.</p>','Сохранить',d=>{const art=+d.get('type'),name=d.get('name').trim();if(!name)return;const entry={id:v?.id||'v'+Date.now(),name,address:d.get('address').trim(),art,type:['Кофейня','Ресторан','Бар','Магазин','Отель','SPA'][art]};if(v)venues[venues.indexOf(v)]=entry;else venues.push(entry);if(!selectedVenue)selectedVenue=entry.id;storedNotice('Заведение сохранено в демо-кабинете');render('venues')})}
function newPlaylist(){modal('Создать плейлист',field('Название плейлиста','name')+'<label class="modal-field">Начальное настроение<select name="track" class="field">'+options(current)+'</select></label><p>Будет создан локальный черновик с выбранным музыкальным эскизом.</p>','Создать',d=>{const name=d.get('name').trim();if(!name)return;customLists.push({name,track:+d.get('track')});storedNotice('Плейлист создан');render('playlists')})}
function editAd(index){const d=drafts[index];modal(d?'Изменить анонс':'Новый анонс',field('Название','name',d?.name||'')+'<label class="modal-field">Текст объявления<textarea class="field" name="text" required maxlength="1000">'+esc(d?.text||'')+'</textarea></label>'+field('Когда планируете использовать','when',d?.when||'','text',false)+'<p>Текстовый черновик. В реальный эфир не отправляется.</p>','Сохранить',f=>{const entry={name:f.get('name').trim(),text:f.get('text').trim(),when:f.get('when').trim()};if(!entry.name||!entry.text)return;if(d)drafts[index]=entry;else drafts.push(entry);storedNotice('Анонс сохранён как черновик');render('ads')})}
function sync(){document.body.classList.toggle('playing',!audio.paused);document.querySelector('#play').innerHTML=icon(audio.paused?'play':'pause');document.querySelector('#play').setAttribute('aria-label',audio.paused?'Слушать эскиз':'Пауза');document.querySelector('#play').setAttribute('aria-pressed',String(!audio.paused));document.querySelector('#track-title').textContent=tracks[current].name;document.querySelector('#track-subtitle').textContent=tracks[current].who+' · '+tracks[current].genre+' · аудиоэскиз';document.querySelector('#player-open').className='dock-cover cover cover-'+current;document.querySelector('#favorite').classList.toggle('active-favorite',favs.includes(current));document.querySelector('#favorite').setAttribute('aria-pressed',String(favs.includes(current)))}
async function toggle(){if(!audio.paused){request++;audio.pause();document.querySelector('#play-status').textContent='Пауза';sync();if(screen==='home')render('home',true);return}const r=++request;document.querySelector('#play-status').textContent='Загрузка…';try{await audio.play();if(r===request){document.querySelector('#play-status').textContent='Играет на этом устройстве';sync();if(screen==='home')render('home',true)}}catch(e){if(r===request&&e.name!=='AbortError'){document.querySelector('#play-status').textContent='Ошибка воспроизведения';notify('Не удалось воспроизвести эскиз. Попробуйте ещё раз.')}}}
function selectTrack(n,start=true){request++;audio.pause();current=n;lastTime=0;audio.src='/assets/preview-'+n+'.wav';document.querySelector('#elapsed').textContent='0:00';document.querySelector('#seek').value=0;document.querySelector('#play-status').textContent='Готов к прослушиванию';sync();if(screen==='home'||screen==='playlists')render(screen,true);if(start)toggle()}
function favorite(){favs=favs.includes(current)?favs.filter(i=>i!==current):[...favs,current];save();sync();if(screen==='playlists'||screen==='home')render(screen,true)}
function closeMenu(){document.body.classList.remove('menu-open');document.querySelector('#scrim').hidden=true;document.querySelector('#open-menu').setAttribute('aria-expanded','false')}
const actions={'new-venue':()=>editVenue(),'new-playlist':newPlaylist,'new-ad':()=>editAd(),'toggle-audio':toggle,favorite,'save-schedule':()=>storedNotice('Расписание сохранено для выбранного дня'),'new-zone':()=>{if(!selectedVenue){notify('Сначала добавьте заведение');return}modal('Добавить музыкальную зону',field('Название зоны','name')+'<p>'+esc(venueName(selectedVenue))+' · демонстрационная зона</p>','Добавить',d=>{const name=d.get('name').trim();if(!name)return;zoneList.push({id:'z'+Date.now(),venue:selectedVenue,name,track:0,volume:50,on:false});storedNotice('Зона добавлена в макет');render('zones')})},tour:()=>modal('Ваше пространство звучит','<p>1. Выберите формат в разделе «Плейлисты» и послушайте эскиз.</p><p>2. Добавьте свои заведения и музыкальные зоны.</p><p>3. Настройте расписание для каждого дня.</p><p>Это интерактивный прототип. Данные остаются в браузере, подключения к реальному эфиру пока нет.</p>'),jingle:()=>modal('Бриф на фирменный джингл',field('Название бренда','brand')+field('Какое настроение передать?','mood')+'<p>Бриф добавится в текстовые черновики. Звук здесь не генерируется.</p>','Сохранить бриф',d=>{drafts.push({name:'Бриф: '+d.get('brand').trim(),text:d.get('mood').trim(),when:'Джингл · требуется согласование'});storedNotice('Бриф сохранён в черновиках');render('ads')})};
document.querySelector('#nav').innerHTML=menu.map(([id,label,ico])=>'<button class="nav-link" data-page="'+id+'">'+icon(ico)+label+'</button>').join('');
document.querySelectorAll('[data-icon]').forEach(x=>x.innerHTML=icon(x.dataset.icon));for(const [id,n] of [['search-icon','search'],['notifications','bell'],['profile-chevron','down'],['open-menu','menu'],['close-menu','close'],['modal-close','close'],['previous','prev'],['next','next'],['volume-icon','volume'],['favorite','heart']])document.getElementById(id).innerHTML=icon(n);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)render(b.dataset.page);if(b.dataset.action)actions[b.dataset.action]?.();if(b.hasAttribute('data-filter')){filter=b.dataset.filter;render(screen,true)}if(b.hasAttribute('data-day')){day=+b.dataset.day;render(screen,true)}if(b.hasAttribute('data-play-track'))selectTrack(+b.dataset.playTrack);if(b.hasAttribute('data-play-slot'))selectTrack(slots()[+b.dataset.playSlot]);if(b.dataset.venueZones){selectedVenue=b.dataset.venueZones;render('zones')}if(b.dataset.editVenue)editVenue(b.dataset.editVenue);if(b.hasAttribute('data-edit-ad'))editAd(+b.dataset.editAd);if(b.dataset.toggleZone){const z=zoneList.find(x=>x.id===b.dataset.toggleZone);z.on=!z.on;b.setAttribute('aria-pressed',String(z.on));save()}if(b.hasAttribute('data-close-modal'))dialog.close()});
document.querySelector('#modal-form').onsubmit=e=>{e.preventDefault();modalSubmit?.(new FormData(e.target));dialog.close()};document.querySelector('#modal-close').onclick=()=>dialog.close();document.querySelector('#add-venue').onclick=()=>editVenue();document.querySelector('#play').onclick=toggle;document.querySelector('#previous').onclick=()=>selectTrack((current+3)%4);document.querySelector('#next').onclick=()=>selectTrack((current+1)%4);document.querySelector('#favorite').onclick=favorite;document.querySelector('#player-open').onclick=()=>render('playlists');document.querySelector('#volume').oninput=e=>{audio.volume=+e.target.value/100;document.querySelector('#volume-value').textContent=e.target.value+'%'};
const time=s=>Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0');audio.addEventListener('loadedmetadata',()=>{document.querySelector('#duration').textContent=time(audio.duration)});audio.addEventListener('timeupdate',()=>{const now=audio.currentTime;if(!audio.paused&&now>=lastTime&&now-lastTime<3)playedSeconds+=now-lastTime;lastTime=now;document.querySelector('#elapsed').textContent=time(now);document.querySelector('#seek').value=audio.duration?now/audio.duration*100:0});audio.addEventListener('playing',sync);audio.addEventListener('pause',sync);audio.addEventListener('error',()=>{document.querySelector('#play-status').textContent='Аудио недоступно';sync();notify('Эскиз недоступен. Выберите другое настроение.')});document.querySelector('#seek').oninput=e=>{if(Number.isFinite(audio.duration)){audio.currentTime=+e.target.value/100*audio.duration;lastTime=audio.currentTime}};
document.querySelector('#search-form').onsubmit=e=>{e.preventDefault();query=document.querySelector('#global-search').value.trim();if(query)render('search',true)};document.querySelector('#notifications').onclick=()=>modal('Уведомления','<p>Пока новых уведомлений нет. События реального аккаунта появятся после подключения кабинета.</p>');document.querySelector('#profile').onclick=()=>modal('Нико · владелец','<p>Вы просматриваете демо-кабинет PROMO.AIR.</p><p><a class="button primary" href="https://promo-music.ru/login">Войти в действующий аккаунт</a></p>');document.querySelector('#open-menu').onclick=()=>{document.body.classList.add('menu-open');document.querySelector('#scrim').hidden=false;document.querySelector('#open-menu').setAttribute('aria-expanded','true')};document.querySelector('#close-menu').onclick=closeMenu;document.querySelector('#scrim').onclick=closeMenu;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});window.addEventListener('popstate',()=>render(location.hash.slice(1)||'home'));window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'home';if(next!==screen)render(next)});
render(pages[location.hash.slice(1)]?location.hash.slice(1):'home');
})();
